-- PolyBrain 本機開發用：重建 Hibernate 有 mapping 的 13 張表並塞假資料。會清掉這些表的資料。
-- 用法：mysql -uroot -p polybrain < db/dev-seed.sql
-- 競標時間用 NOW() 推算，重跑一次就會刷新成「進行中 / 即將開始 / 已結標」。
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS ORDER_DETAIL;
DROP TABLE IF EXISTS ITEM_ORDER;
DROP TABLE IF EXISTS CART;
DROP TABLE IF EXISTS ITEM_IMAGE;
DROP TABLE IF EXISTS Item;
DROP TABLE IF EXISTS BID_ORDER_DETAIL;
DROP TABLE IF EXISTS BID_ORDER;
DROP TABLE IF EXISTS BID_EVENT;
DROP TABLE IF EXISTS BID_ITEM_PIC;
DROP TABLE IF EXISTS BID_ITEM;
DROP TABLE IF EXISTS ITEM_CLASS;
DROP TABLE IF EXISTS employee;
DROP TABLE IF EXISTS MEMBER;
SET FOREIGN_KEY_CHECKS = 1;
create table BID_EVENT (
       BID_EVENT_NO integer not null auto_increment,
        BID_ITEM_NO integer,
        CLOSE_TIME datetime,
        DIRECTIVE_PRICE integer,
        FLOOR_PRICE integer,
        LEAST_OFFERS integer,
        START_TIME datetime,
        primary key (BID_EVENT_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table BID_ITEM (
       BID_ITEM_NO integer not null auto_increment,
        BID_ITEM_DESCRIBE text,
        BID_ITEM_NAME varchar(255),
        GAME_PUBLISHER varchar(255),
        ITEM_CLASS_NO integer,
        primary key (BID_ITEM_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table BID_ITEM_PIC (
       BID_ITEM_PIC_NO integer not null auto_increment,
        BID_ITEM_NO integer,
        BID_ITEM_PIC longblob,
        primary key (BID_ITEM_PIC_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table BID_ORDER (
       BID_ORDER_NO integer not null auto_increment,
        BID_EVENT_NO integer,
        BID_ITEM_NO integer,
        FINAL_PRICE integer,
        MEM_NO integer,
        primary key (BID_ORDER_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table BID_ORDER_DETAIL (
       bod_no integer not null auto_increment,
        bid_order_no integer,
        receiver_address varchar(255),
        receiver_method integer,
        receiver_Name varchar(255),
        receiver_phone varchar(255),
        primary key (bod_no)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table CART (
       ITEM_NO integer not null,
        MEM_NO integer not null,
        quantity integer,
        primary key (ITEM_NO, MEM_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table employee (
       EMP_NO integer not null auto_increment,
        EMP_EMAIL varchar(255),
        EMP_GENDER tinyint,
        EMP_NAME varchar(255),
        EMP_PH varchar(255),
        EMP_PIC longblob,
        EMP_PWD varchar(255),
        EMP_STATE tinyint,
        primary key (EMP_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table Item (
       ITEM_NO integer not null auto_increment,
        GAME_TIME integer,
        ITEM_CLASS_NO integer,
        ITEM_NAME varchar(255),
        ITEM_PRICE integer,
        ITEM_PROD_DESCRIPTION text,
        ITEM_QTY integer,
        ITEM_SALES integer,
        ITEM_STATE integer,
        MAX_PLAYER integer,
        MIN_PLAYER integer,
        primary key (ITEM_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table ITEM_CLASS (
       item_Class_No integer not null auto_increment,
        ITEM_CLASS_NAME varchar(255),
        primary key (item_Class_No)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table ITEM_IMAGE (
       item_ImgNo integer not null auto_increment,
        item_Img longtext,
        item_No integer,
        primary key (item_ImgNo)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table ITEM_ORDER (
       ORDER_NO integer not null auto_increment,
        MEM_NO integer,
        ORDER_STATE integer,
        ORDER_TOTAL integer,
        RECEIVER_ADDRESS varchar(255),
        RECEIVER_METHOD integer,
        RECEIVER_NAME varchar(255),
        RECEIVER_PHONE varchar(255),
        TRAN_TIME date default (curdate()),
        primary key (ORDER_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table MEMBER (
       MEM_NO integer not null auto_increment,
        MEM_ADDRS varchar(255),
        MEM_AUTH tinyint,
        MEM_BIRTH date,
        MEM_EMAIL varchar(255),
        MEM_GENDER tinyint,
        MEM_NAME varchar(255),
        MEM_PH varchar(255),
        MEM_PIC longblob,
        MEM_PID varchar(255),
        MEM_PWD varchar(255),
        MEM_VIO tinyint,
        primary key (MEM_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    create table ORDER_DETAIL (
       ITEM_NO integer not null,
        ORDER_NO integer not null,
        ITEM_PRICE integer,
        ITEM_SALES integer,
        primary key (ITEM_NO, ORDER_NO)
    ) engine=InnoDB default charset=utf8mb4;


    
    alter table BID_EVENT 
       add constraint FK5kx6ra730ld77xb0kxn95rp3c 
       foreign key (BID_ITEM_NO) 
       references BID_ITEM (BID_ITEM_NO);


    
    alter table BID_ITEM 
       add constraint FKf34kr6t0kf31oh3ik08ucc71c 
       foreign key (ITEM_CLASS_NO) 
       references ITEM_CLASS (item_Class_No);


    
    alter table BID_ITEM_PIC 
       add constraint FKdl86bl8pgvdv7tt6o419elms0 
       foreign key (BID_ITEM_NO) 
       references BID_ITEM (BID_ITEM_NO);


    
    alter table BID_ORDER 
       add constraint FKfamo2v9utifej213unjb4chbe 
       foreign key (BID_EVENT_NO) 
       references BID_EVENT (BID_EVENT_NO);


    
    alter table BID_ORDER 
       add constraint FKteif0l8s47e2n8bjwl88vacwd 
       foreign key (BID_ITEM_NO) 
       references BID_ITEM (BID_ITEM_NO);


    
    alter table BID_ORDER 
       add constraint FKbfca5sggpkav29c926g6shds1 
       foreign key (MEM_NO) 
       references MEMBER (MEM_NO);


    
    alter table BID_ORDER_DETAIL 
       add constraint FK8byxyxxtlllb7nmvpg97cct4k 
       foreign key (BID_ORDER_NO) 
       references BID_ORDER (BID_ORDER_NO);


    
    alter table Item 
       add constraint FK64r9x5eki186strxffqeuw2ur 
       foreign key (ITEM_CLASS_NO) 
       references ITEM_CLASS (item_Class_No);


    
    alter table ITEM_IMAGE 
       add constraint FKhyrwvb3ctyr8v0g5134fclxl6 
       foreign key (ITEM_NO) 
       references Item (ITEM_NO);


    
    alter table ITEM_ORDER 
       add constraint FKgm7rwbp8u0kejln62wn6bt2kx 
       foreign key (MEM_NO) 
       references MEMBER (MEM_NO);

